def tau(a, b):
    k = d = 0
    n = len(a)
    for i in range(n):
        for j in range(i + 1, n):
            s = (a[i] - a[j]) * (b[i] - b[j])
            k += s > 0
            d += s < 0
    return k, d, round((k - d) / (n * (n - 1) / 2), 4)

